+      if (result !== "allowed" && result !== "denied")
+        assert.fail(`unknown result ${result} for ${label}`);
+      if (written !== (result === "allowed"))
+        mismatches.push(`${label}: expected ${result}`);
+    }
+    assert.deepEqual(mismatches, []);
+  },
