  supabase,
  tableName,
  insertData,
  uniqueOn = undefined,
}: {
  supabase: SupabaseClient<Database, "public">;
  tableName: TableName;
  insertData: RawTablesInsert<TableName>;
  uniqueOn?: RawTablesInsertKey<TableName>[];
